#include <stdio.h>

typedef long long ll;
#define INF 1000000000000000000LL

ll xs[1005][2], ys[1005][2];
ll dist[1005];
int used[1005];

/* custo minimo (Manhattan) de deslocamento descoberto entre duas regiões
   (pontos são retângulos degenerados) */
static inline ll w(int a, int b){
    ll gx = 0, gy = 0;
    if (xs[a][1] < xs[b][0]) gx = xs[b][0] - xs[a][1];
    else if (xs[b][1] < xs[a][0]) gx = xs[a][0] - xs[b][1];
    if (ys[a][1] < ys[b][0]) gy = ys[b][0] - ys[a][1];
    else if (ys[b][1] < ys[a][0]) gy = ys[a][0] - ys[b][1];
    return gx + gy;
}

int main(void){
    ll xi, yi, xf, yf, a, b, c, d, t;
    if (scanf("%lld %lld %lld %lld", &xi, &yi, &xf, &yf) != 4) return 0;

    /* no 0: ponto inicial; no 1: ponto final; nos 2..N+1: retângulos */
    xs[0][0] = xs[0][1] = xi; ys[0][0] = ys[0][1] = yi;
    xs[1][0] = xs[1][1] = xf; ys[1][0] = ys[1][1] = yf;

    int N;
    scanf("%d", &N);
    for (int i = 0; i < N; i++){
        scanf("%lld %lld %lld %lld", &a, &b, &c, &d);
        if (a > c){ t = a; a = c; c = t; }
        if (b > d){ t = b; b = d; d = t; }
        xs[2+i][0] = a; xs[2+i][1] = c;
        ys[2+i][0] = b; ys[2+i][1] = d;
    }

    int n = N + 2;
    for (int i = 0; i < n; i++){ dist[i] = INF; used[i] = 0; }
    dist[0] = 0;

    /* Dijkstra O(n^2) */
    for (int it = 0; it < n; it++){
        int u = -1;
        for (int i = 0; i < n; i++)
            if (!used[i] && (u < 0 || dist[i] < dist[u])) u = i;
        if (u < 0 || dist[u] >= INF) break;
        used[u] = 1;
        for (int v = 0; v < n; v++){
            if (used[v]) continue;
            ll nd = dist[u] + w(u, v);
            if (nd < dist[v]) dist[v] = nd;
        }
    }

    printf("%lld\n", dist[1]);
    return 0;
}
